<?php require_role('student'); $pageTitle='Student Dashboard';$pageSubtitle='Your project progress and supervision activity';$project=project_for_student((int)current_user()['id']);$progress=$project?progress_for_project((int)$project['id']):0;
$sessions=$project?db_all("SELECT * FROM sessions WHERE project_id=? ORDER BY scheduled_at DESC LIMIT 5",[$project['id']]):[];
$milestones=$project?db_all("SELECT * FROM milestones WHERE project_id=? ORDER BY due_date IS NULL,due_date,id LIMIT 6",[$project['id']]):[];
$next=$project?db_one("SELECT * FROM sessions WHERE project_id=? AND status IN('approved','rescheduled') AND scheduled_at>=CURRENT_TIMESTAMP ORDER BY scheduled_at LIMIT 1",[$project['id']]):null;
$approved=$project?(int)(db_one("SELECT COUNT(*) c FROM milestones WHERE project_id=? AND status='approved'",[$project['id']])['c']??0):0;$total=count($milestones);
include __DIR__.'/../includes/layout_top.php'; ?>
<?php if(!$project): ?><div class="card empty-state"><h2>No project assignment yet</h2><p>Your account is active, but the project coordinator has not assigned a supervisor and project title.</p></div><?php else: ?>
<div class="stats-grid"><div class="stat-card"><div class="stat-label">Overall progress</div><div class="stat-value"><?= $progress ?>%</div><div class="stat-note">Based on approved weighted milestones</div></div><div class="stat-card"><div class="stat-label">Approved milestones</div><div class="stat-value"><?= $approved ?>/<?= $total ?></div><div class="stat-note">Current stage: <?= e($project['current_stage']) ?></div></div><div class="stat-card"><div class="stat-label">Completed sessions</div><div class="stat-value"><?= (int)(db_one("SELECT COUNT(*) c FROM sessions WHERE project_id=? AND status='completed'",[$project['id']])['c']??0) ?></div><div class="stat-note">Structured feedback records</div></div><div class="stat-card"><div class="stat-label">Next session</div><div class="stat-value" style="font-size:1.25rem"><?= $next?e(format_date($next['scheduled_at'],'d M, h:i A')):'Not booked' ?></div><div class="stat-note"><?= $next?e(ucfirst($next['mode'])):'Request a new session' ?></div></div></div>
<div class="dashboard-grid"><section><div class="card"><div class="card-header"><div><h2>My final-year project</h2><p><?= e($project['status']) ?> project record</p></div><span class="badge <?= status_class($project['status']) ?>"><?= e($project['status']) ?></span></div><div class="project-title"><?= e($project['title']) ?></div><div class="meta-row"><span>Supervisor: <strong><?= e($project['supervisor_name'] ?: 'Not assigned') ?></strong></span><span>Due: <strong><?= e(format_date($project['due_date'],'d M Y')) ?></strong></span><span>Stage: <strong><?= e($project['current_stage']) ?></strong></span></div><div style="margin-top:22px"><div class="progress-row"><span>Approved progress</span><span><?= $progress ?>%</span></div><div class="progress-track"><div class="progress-bar" data-progress="<?= $progress ?>"></div></div></div></div>
<div class="card"><div class="card-header"><div><h2>Milestone roadmap</h2><p>Submission and approval status</p></div><a class="button small secondary" href="<?= e(url('index.php?page=student-milestones')) ?>">View all</a></div><div class="timeline"><?php foreach($milestones as $m): ?><div class="timeline-item"><span class="timeline-dot"></span><h4><?= e($m['title']) ?> <span class="badge <?= status_class($m['status']) ?>"><?= e(str_replace('_',' ',$m['status'])) ?></span></h4><p><?= e($m['due_date']?'Due '.format_date($m['due_date'],'d M Y'):'No due date set') ?> · Weight <?= (int)$m['weight'] ?>%</p></div><?php endforeach; ?></div></div></section>
<aside><div class="card"><div class="card-header"><div><h3>Recent sessions</h3><p>Latest supervision activity</p></div></div><?php if(!$sessions): ?><div class="empty-state">No supervision sessions yet.</div><?php else: foreach($sessions as $s): ?><div class="list-card"><div><h4><?= e(format_date($s['scheduled_at'],'d M Y')) ?></h4><p><?= e($s['agenda']) ?></p></div><span class="badge <?= status_class($s['status']) ?>"><?= e($s['status']) ?></span></div><?php endforeach; endif; ?><a class="button small w-full" style="margin-top:16px" href="<?= e(url('index.php?page=student-sessions')) ?>">Request supervision session</a></div>
<div class="card"><div class="card-header"><h3>Supervisor contact</h3></div><div class="student-head"><div class="avatar"><?= e(strtoupper(substr($project['supervisor_name']?:'S',0,1))) ?></div><div><h3><?= e($project['supervisor_name']?:'Not assigned') ?></h3><p><?= e($project['supervisor_email']?:'') ?></p></div></div><a class="button small secondary w-full" href="<?= e(url('index.php?page=messages')) ?>">Open messages</a></div></aside></div>
<?php endif; include __DIR__.'/../includes/layout_bottom.php'; ?>
